    ---------------------------------------------------------------------------
    [211931] = {
        name = "Chifre Chamador do Abismo (Abyss Caller Horn)",
        sourceType = "VENDOR",
        zone = "Dornogal",
        coords = "47.6, 43.6",
        target = "Sir Finley Mrrgglton (Sede dos Exploradores)",
        cost = "500 Cristais de Ressonância (500 Undercoin na TWW S1)",
        difficulty = "Fácil",
        guide = "1. Viaja até Dornogal, a capital da Ilha de Dorn.\n2. Dirige-te à Sede dos Exploradores (Delver's Headquarters), no centro da cidade (47.6, 43.6).\n3. Fala com Sir Finley Mrrgglton, ao lado de Brann Barbabronze.\n4. Compra o Chifre Chamador do Abismo por 500 Cristais de Ressonância.\n5. Usa o brinquedo para criar um corpo de água: podes nadar dentro da bolha e não precisas de respirar!",
        waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton"
    },
    [228705] = {
        name = "Soro Aracnídeo (Arachnoserum)",
        sourceType = "VENDOR",
        zone = "Azj-Kahet",
        coords = "55.3, 41.2",
        target = "Lady Vinazian, Quartel-mestre dos Fios Cortados (Weaver's Lair) — alternativa: Y'tekhi (57.6, 46.8)",
        cost = "1.750 Ouro",
        difficulty = "Fácil",
        guide = "1. Viaja até Azj-Kahet (Khaz Algar) e entra no Weaver's Lair.\n2. Encontra Lady Vinazian, a quartel-mestre dos Fios Cortados, na plataforma (55.3, 41.2).\n3. Compra o Soro Aracnídeo por 1.750 ouro.\n4. Usa o brinquedo para te transformares numa aranha gigante (cooldown 60 min).",
        waypoint = "/way Azj-Kahet 55.3 41.2 Lady Vinazian"
    },
    [200707] = {
        name = "Armário de Capas Infinitas (Armoire of Endless Cloaks)",
        sourceType = "VENDOR",
        zone = "Costas Despertas (The Waking Shores)",
        coords = "28.7, 47.3",
        target = "Lorena Belle e Atticus Belle (Trono Obsidiano)",
        cost = "20 Tecidos Silvestres Esfarrapados + 100 Suprimentos das Ilhas do Dragão",
        difficulty = "Fácil",
        guide = "1. Viaja até ao Trono Obsidiano (Obsidian Throne), na parte oeste das Costas Despertas (28.7, 47.3).\n2. Fala com Lorena Belle (área superior) ou Atticus Belle (piso térreo), agentes de Wrathion.\n3. Requer reputação 'Cohort' com Wrathion.\n4. Compra o Armário de Capas Infinitas por 20 Tecidos Silvestres Esfarrapados + 100 Suprimentos das Ilhas do Dragão.\n5. Usa para aceder à coleção pessoal de capas do Wrathion (cooldown 15 min).",
        waypoint = "/way The Waking Shores 28.7 47.3 Trono Obsidiano"
    },
    [259899] = {
        name = "Chifre Cinzento do Guardião Caído (Ashen Horn of the Fallen Keeper)",
        sourceType = "VENDOR",
        zone = "Valdrakken",
        coords = "81.4, 47.3",
        target = "Xydan (vendedor de Timewalking de Dragonflight, Bronze Enclave)",
        cost = "750 Insígnias Distorcidas no Tempo (Timewarped Badges)",
        difficulty = "Médio",
        guide = "1. Este vendedor só aparece em Valdrakken durante a semana de Timewalking de Dragonflight (evento Turbulent Timeways).\n2. Dirige-te ao Bronze Enclave, na zona leste da cidade, plataforma (81.4, 47.3).\n3. Fala com Xydan e compra o Chifre Cinzento do Guardião Caído por 750 Insígnias Distorcidas no Tempo (ganhas em masmorras Timewalking).\n4. Usa para ficar envolto em cinzas enquanto brasas de Amirdrassil caem sobre ti (cooldown 30 min).",
        waypoint = "/way Valdrakken 81.4 47.3 Xydan"
    },
    [199649] = {
        name = "Conjunto de Chá do Dragão (Dragon Tea Set)",
        sourceType = "QUEST",
        zone = "Valdrakken",
        coords = "46.5, 46.3",
        target = "Erugosa (Taverna do Carneiro Assado, Roasted Ram)",
        cost = "Recompensa da missão 'To Cook With Finery' (também vendido por Erugosa)",
        difficulty = "Fácil",
        guide = "1. Viaja até Valdrakken e entra na Taverna do Carneiro Assado (Roasted Ram), na parte sul da cidade (46.5, 46.3).\n2. Fala com Erugosa, a dragão azul na cozinha.\n3. Completa a missão de culinária 'To Cook With Finery' — o Conjunto de Chá do Dragão é uma das recompensas possíveis.\n4. Alternativamente, compra-o diretamente a Erugosa.\n5. Usa para servir chá (cooldown 1 hora).",
        waypoint = "/way Valdrakken 46.5 46.3 Erugosa"
    },
    [202021] = {
        name = "Bandeira da Vitória do Quebrador (Breaker's Flag of Victory)",
        sourceType = "VENDOR",
        zone = "Valdrakken",
        coords = "44.6, 36.9",
        target = "Warkeeper Gresh (Refúgio do Gladiador, Gladiator's Refuge)",
        cost = "1.500 Tokens Sangrentos (Bloody Tokens)",
        difficulty = "Médio",
        guide = "1. Viaja até Valdrakken e entra no Refúgio do Gladiador, a oeste da cidade (44.6, 36.9).\n2. Fala com Warkeeper Gresh, o vendedor de PvP que vende por Tokens Sangrentos.\n3. Ganha Tokens Sangrentos em World Quests de PvP e no modo de guerra.\n4. Compra a Bandeira da Vitória do Quebrador por 1.500 Tokens Sangrentos.\n5. Usa para colocar uma bandeira no cadáver de um jogador inimigo à tua frente (cooldown 60 seg).",
        waypoint = "/way Valdrakken 44.6 36.9 Warkeeper Gresh"
    },
    [228698] = {
