        difficulty = "Farm",
        guide = "1. Desbloqueia A Assembleia das Profundezas (completa a campanha de Khaz Algar até 'Back to Gundargaz') e sobe até Renome 18.\n2. Viaja até Gundargaz, a capital kobold no Fosso Profundo (47.3, 32.6).\n3. Fala com Waxmonger Squick, o quartel-mestre da facção.\n4. Compra o Haltere do Dobrador de Velas por 5.000 Cristais de Ressonância.\n5. Usa para invocar Lil Wick, que te carrega (só funciona em exteriores; cooldown 1 hora).",
        waypoint = "/way The Ringing Deeps 47.3 32.6 Waxmonger Squick"
    },
